    if (!al_init()) {
        al_show_native_message_box(NULL, "Error", "Failed to initialize Allegro", NULL, NULL, ALLEGRO_MESSAGEBOX_ERROR);
        return -1;
    }

    ALLEGRO_DISPLAY *display = al_create_display(SCREEN_WIDTH, SCREEN_HEIGHT);
    if (!display) {
        al_show_native_message_box(NULL, "Error", "Failed to create display", NULL, NULL, ALLEGRO_MESSAGEBOX_ERROR);
