    ALLEGRO_BITMAP *snake_head = al_load_bitmap("snake_head.png");
    ALLEGRO_BITMAP *snake_body = al_load_bitmap("snake_body.png");
    ALLEGRO_BITMAP *food = al_load_bitmap("food.png");

    if (!snake_head || !snake_body || !food) {
        al_show_native_message_box(NULL, "Error", "Failed to load images", NULL, NULL, ALLEGRO_MESSAGEBOX_ERROR);
        return -1;
    }

    // Initialize game state
    // ...

    // Main game loop
    // ...

    al_destroy_bitmap(snake_head);
    al_destroy_bitmap(snake_body);
    al_destroy_bitmap(food);
    al_destroy_display(display);
    al_uninstall_system();
    return 0;
}
```

### Step 5: Game Logic
Implement the game logic, including snake movement, collision detection, and food spawning.

```c
typedef struct {
    int x, y;
} SnakePart;

SnakePart snake[100];
int snake_length = 3;
int direction = 0; // 0: right, 1: down, 2: left, 3: up
int food_x, food_y;

void init_game() {
    srand(time(NULL));
    food_x = rand() % (SCREEN_WIDTH / SNAKE_SIZE) * SNAKE_SIZE;
    food_y = rand() % (SCREEN_HEIGHT / SNAKE_SIZE) * SNAKE_SIZE;

    for (int i = 0; i < snake_length; i++) {
        snake[i].x = SCREEN_WIDTH / 2 - i * SNAKE_SIZE;
        snake[i].y = SCREEN_HEIGHT / 2;
    }
}

void move_snake() {
    // Move the snake
    for (int i = snake_length - 1; i > 0; i--) {
        snake[i].x = snake[i - 1].x;
        snake[i].y = snake[i - 1].y;
    }

    switch (direction) {
        case 0: snake[0].x += SNAKE_SIZE; break;
        case 1: snake[0].y += SNAKE_SIZE; break;
        case 2: snake[0].x -= SNAKE_SIZE; break;
        case 3: snake[0].y -= SNAKE_SIZE; break;
    }

    // Check for collision with food
    if (snake[0].x == food_x && snake[0].y == food_y) {
        snake_length++;
        food_x = rand() % (SCREEN_WIDTH / SNAKE_SIZE) * SNAKE_SIZE;
        food_y = rand() % (SCREEN_HEIGHT / SNAKE_SIZE) * SNAKE_SIZE;
    }

    // Check for collision with walls or itself
    if (snake[0].x < 0 || snake[0].x >= SCREEN_WIDTH || snake[0].y < 0 || snake[0].y >= SCREEN_HEIGHT) {
        // Game over
    }
    for (int i = 1; i < snake_length; i++) {
        if (snake[0].x == snake[i].x && snake[0].y == snake[i].y) {
            // Game over
        }
    }
}
```

### Step 6: Drawing the Game
Draw the snake and food on the screen.

```c
void draw_game() {
    al_clear_to_color(al_map_rgb(0, 0, 0));

    // Draw snake
    for (int i = 0; i < snake_length; i++) {
        if (i == 0) {
            al_draw_bitmap(snake_head, snake[i].x, snake[i].y, 0);
        } else {
            al_draw_bitmap(snake_body, snake[i].x, snake[i].y, 0);
        }
    }

    // Draw food
    al_draw_bitmap(food, food_x, food_y, 0);

    al_flip_display();
}
```

### Step 7: Main Game Loop
Combine everything into the main game loop.

```c
int main() {
    // Initialize Allegro and load images
    // ...

    init_game();

    ALLEGRO_EVENT_QUEUE *event_queue = al_create_event_queue();
    al_register_event_source(event_queue, al_get_keyboard_event_source());
    al_register_event_source(event_queue, al_get_display_event_source(display));

    ALLEGRO_TIMER *timer = al_create_timer(1.0 / SNAKE_SPEED);
    al_start_timer(timer);
    al_register_event_source(event_queue, al_get_timer_event_source(timer));

    bool game_running = true;
    while (game_running) {
        ALLEGRO_EVENT event;
        al_wait_for_event(event_queue, &event);

        if (event.type == ALLEGRO_EVENT_DISPLAY_CLOSE) {
            game_running = false;
        } else if (event.type == ALLEGRO_EVENT_TIMER) {
            move_snake();
            draw_game();
        } else if (event.type == ALLEGRO_EVENT_KEY_DOWN) {
            switch (event.keyboard.keycode) {
                case ALLEGRO_KEY_UP: direction = 3; break;
                case ALLEGRO_KEY_DOWN: direction = 1; break;
                case ALLEGRO_KEY_LEFT: direction = 2; break;
                case ALLEGRO_KEY_RIGHT: direction = 0; break;
            }
        }
    }

    // Cleanup
    // ...

    return 0;
}
```

### Step 8: Compile and Run
Compile your game using a C compiler that supports Allegro, such as GCC.

```sh
gcc -o snake_game snake_game.c -lallegro -lallegro_image -lallegro_primitives
./snake_game
```

This is a basic framework for a snake game using Allegro in C. You can expand upon this by adding more features, improving the graphics, and refining the game mechanics.

