function isPrime(num) {
    if (num <= 1) return false; // 0 and 1 are not prime numbers
    if (num <= 3) return true; // 2 and 3 are prime numbers
    if (num % 2 === 0 || num % 3 === 0) return false; // Eliminate multiples of 2 and 3

    for (let i = 5; i * i <= num; i += 6) {
        if (num % i === 0 || num % (i + 2) === 0) return false;
    }
    return true;
}

function checkPrimesInArray(arr) {
    if (arr.length !== 5) {
        console.log("The array must contain exactly 5 numbers.");
        return;
    }

    for (let i = 0; i < arr.length; i++) {
        if (isPrime(arr[i])) {
            console.log(arr[i] + " is a prime number.");
        }
    }
}

// Example usage:
const numbers = [2, 4, 7, 11, 15];
checkPrimesInArray(numbers);
```

### Explanation:
1. **isPrime Function**: This function checks if a given number is prime. It first handles the base cases (numbers less than or equal to 1 are not prime, and 2 and 3 are prime). Then it checks for divisibility by 2 and 3. For larger numbers, it uses a loop that checks divisibility up to the square root of the number, incrementing by 6 each time (this is an optimization to skip even numbers and multiples of 3).

2. **checkPrimesInArray Function**: This function takes an array as input, checks if the array has exactly 5 elements, and then iterates through the array to check each number using the `isPrime` function. If a number is prime, it prints the number to the console.

3. **Example Usage**: The example usage demonstrates how to call the `checkPrimesInArray` function with an array of 5 numbers.

You can test this function with different arrays of 5 numbers to see which numbers are prime.

